        } else {
            if (timeZone > 9) {
                out.write('+');
                out.writeInt(timeZone);
            } else if (timeZone > 0) {
                out.write('+');
                out.write('0');
                out.writeInt(timeZone);
            } else if (timeZone < -9) {
                out.write('-');
                out.writeInt(-timeZone);
            } else if (timeZone < 0) {
                out.write('-');
                out.write('0');
                out.writeInt(-timeZone);
            }
            out.write(':');
            int offSet = (int)(Math.abs(timeZoneF - timeZone) * 60);
            out.append(String.format("%02d", offSet));
        }

        out.write(quote);
    } else {
        out.writeLong(time);
